/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Process Price Change tracking records and create Price Data Feed records
/// </summary>
using Microsoft.Dynamics.AX.Platform.Extensibility;
[ExportInterface()]
abstract class METPriceChangeTrack
{
    const public str        blankValue = '';
    METPriceChangeTracking  priceChangeTrackingOrig;
    RecordInsertList        priceDataFeedList;
    METPriceDataFeed        priceDataFeed;
    counter                 priceDataFeedCount;
    TransDate               todayDate;
    boolean                 showValidation;

    container   discountTypesCon;
    RefRecId    pricingRuleHeaderPrevious, linePricingRulePrevious;
    Set         custAccountRelatedSet, inventItemRelatedSet;

}

Method.Source:
/// <summary>
/// Process the Source record that triggered the change
/// </summary>
abstract void process()
{
}

/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_priceChangeTracking">Table record</param>
/// <param name = "_showValidation">Show validation</param>
public void initInstance(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    this.setInternals(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>the proce change type</returns>
abstract METPriceChangeType getPriceChangeType()
{
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_priceChangeTracking">Price Change Tracking record</param>
/// <param name = "_showValidation">Show validation</param>
public void setInternals(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    priceChangeTrackingOrig = _priceChangeTracking;
    todayDate           = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
    showValidation      = _showValidation;
}

    /// <summary>
    /// Validate the Item / Site combination
    /// </summary>
    /// <param name = "_itemId">Item</param>
    /// <param name = "_inventSiteId">Site</param>
    /// <returns>result of validation</returns>
    public boolean itemSiteValidation(ItemId _itemId, InventSiteId _inventSiteId)
    {
        InventItemSalesSetup        inventItemSalesSetup;
        METItemSiteSettingsSetup    itemSiteSettingsSetup;
        str                         message;

        boolean validityCheck = true;

        //1. Is Default setting missing,  Is Item stopped for Sale?
        inventItemSalesSetup = inventItemSalesSetup::find(_ItemId, this.getInventDimIdFromSite(_inventSiteId));

        if(!inventItemSalesSetup || inventItemSalesSetup.isStopped())
        {
            validityCheck = false;
            if(showValidation)
            {
                message +=  strFmt('Item / Site default setting is missing or stopped for item:%1 and site:%2\n', _ItemId, _inventSiteId);
            }
        }
                
        if(validityCheck)
        {
            //2. Is Site specific setting missing
            itemSiteSettingsSetup = METItemSiteSettingsSetup::find(_ItemId, _inventSiteId);
        
            if(!itemSiteSettingsSetup)
            {
                validityCheck = false;
                if(showValidation)
                {
                    message +=  strFmt('Site specific setting is missing for item:%1 and site:%2\n', _ItemId, _inventSiteId);
                }
            }
        }

        if(validityCheck)
        {
            //3. Are all 3 "Publish" parameters on the Master OR Site setting set to No?
            if(itemSiteSettingsSetup.isPublishNone() || METInventPriceChange::isPublishNone())
            {
                validityCheck = false;

                if(showValidation)
                {
                    message +=  strFmt('All 3 "Publish" parameters on the Master / Site setting set to No for item:%1 and site:%2\n', _ItemId, _inventSiteId);
                }
            }
        }

        if(showValidation && message)
        {
            this.sendMessage(message);
        }

        return validityCheck;
    }

    /// <summary>
    /// Validate the Customer / Item combination
    /// </summary>
    /// <param name = "_custAccount">Customer</param>
    /// <param name = "_itemId">Item</param>
    /// <returns>Validation result</returns>
    public boolean customerItemValidation(CustAccount _custAccount, ItemId _itemId)
    {
        boolean                 validityCheck = false;
        METCustTable            metCustTable;
        CustTable               custTable;
        LogisticsPostalAddress  logisticsPostalAddress;
        str                     message;

        //1. Does a Profile customer record exist. Master setting, exit if True.
        if(METProfileCustTable::exist(_custAccount))
        {
            validityCheck = true;

            if(showValidation)
            {
                message += strFmt('Profile customer record found for account:%1\n', _custAccount);
            }

            return validityCheck;
        }

        //2. Work though combinations of "Only sell to" and find a reason to change "validityCheck = true"
        if(!validityCheck)
        {
            //a. no entries in “Only sell to" for Item
            if(!METSalesOrderGuideItem::existForItem(_ItemId))
            {
                validityCheck = true;

                if(showValidation)
                {
                    message += strFmt('No Only sell to record for item:%1\n', _ItemId);
                }
            }

            //b. entry in the “Only sell to” for Item number and Customer
            if(!validityCheck && METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::Customer, _custAccount, METSalesOrderGuideInclusion::Include))
            {
                validityCheck = true;

                if(showValidation)
                {
                    message += strFmt('Only sell to record for item:%1 and customer:%2\n', _ItemId, _custAccount);
                }
            }

            //c. entry in the “Only sell to” for Item number and Customer Operation group
            if(!validityCheck)
            {
                select firstonly CustOperGroupId from metCustTable
                    where   metCustTable.AccountNum == _custAccount;

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::CustomerOperationsGroup, metCustTable.CustOperGroupId, METSalesOrderGuideInclusion::Include))
                {
                    validityCheck = true;

                    if(showValidation)
                    {
                        message += strFmt('Only sell to record for item:%1 and group:%2\n', _ItemId, metCustTable.CustOperGroupId);
                    }
                }
            }

            //d. entry in the “Only sell to” for Item number and Customer Site
            if(!validityCheck)
            {
                select firstonly InventSiteId, Party from custTable
                    where   custTable.AccountNum == _custAccount;

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::Site, custTable.InventSiteId, METSalesOrderGuideInclusion::Include))
                {
                    validityCheck = true;

                    if(showValidation)
                    {
                        message += strFmt('Only sell to record for item:%1 and site:%2\n', _ItemId, custTable.InventSiteId);
                    }
                }
            }

            //e. entry in the “Only sell to” for Item number and Customer delivery state
            if(!validityCheck)
            {
                logisticsPostalAddress  = DirParty::FindPostalAddressByRole(custTable.Party, LogisticsLocationRoleType::Delivery);

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::State, logisticsPostalAddress.State, METSalesOrderGuideInclusion::Include))
                {
                    validityCheck = true;

                    if(showValidation)
                    {
                        message += strFmt('Only sell to record for item:%1 and state:%2\n', _ItemId, logisticsPostalAddress.State);
                    }
                }
            }
        }

        //3. If ValidityCheck is True, Work though combinations of "Do not sell to" and find a reason to change "validityCheck = false" 
        if(validityCheck)
        {
            //a. entry in the “Do not sell to” for Item number and Customer
            if(validityCheck && METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::Customer, _custAccount, METSalesOrderGuideInclusion::Exclude))
            {
                validityCheck = false;

                if(showValidation)
                {
                    message += strFmt('Do not sell to record for item:%1 and customer:%2\n', _ItemId, _custAccount);
                }
            }

            //b. entry in the “Do not sell to” for Item number and Customer Operation group
            if(validityCheck) 
            {
                select firstonly CustOperGroupId from metCustTable
                    where   metCustTable.AccountNum == _custAccount;

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::CustomerOperationsGroup, metCustTable.CustOperGroupId, METSalesOrderGuideInclusion::Exclude))
                {
                    validityCheck = false;

                    if(showValidation)
                    {
                        message += strFmt('Do not sell to record for item:%1 and group:%2\n', _ItemId, metCustTable.CustOperGroupId);
                    }
                }
            }

            //c. entry in the “Do not sell to” for Item number and Customer Site
            if(validityCheck)
            {
                select firstonly InventSiteId, Party from custTable
                    where   custTable.AccountNum == _custAccount;

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::Site, custTable.InventSiteId, METSalesOrderGuideInclusion::Exclude))
                {
                    validityCheck = false;

                    if(showValidation)
                    {
                        message += strFmt('Do not sell to record for item:%1 and site:%2\n', _ItemId, custTable.InventSiteId);
                    }
                }
            }

            //d. entry in the “Do not sell to” for Item number and Customer delivery state
            if(validityCheck)
            {
                logisticsPostalAddress  = DirParty::FindPostalAddressByRole(custTable.Party, LogisticsLocationRoleType::Delivery);

                if(METSalesOrderGuideItem::exist(_ItemId, METSalesOrderGuideReferenceType::State, logisticsPostalAddress.State, METSalesOrderGuideInclusion::Exclude))
                {
                    validityCheck = false;

                    if(showValidation)
                    {
                        message += strFmt('Do not sell to record for item:%1 and state:%2\n', _ItemId, logisticsPostalAddress.State);
                    }
                }
            }
        }

        if(showValidation && message)
        {
            this.sendMessage(message);
        }

        return validityCheck;
    }

/// <summary>
/// Create a Price data feed record
/// </summary>
/// <param name = "_priceChangeTracking">Price change tracking record</param>
public void createPriceDataFeedBase(METPriceChangeTracking _priceChangeTracking)
{
    priceDataFeed.Clear();
    priceDataFeed.initValue();
    this.initFromPriceChangeTracking();
    priceDataFeed.ItemId        = _priceChangeTracking.ItemId;
    priceDataFeed.CustAccount   = _priceChangeTracking.PriceDiscAccountRelation;
    priceDataFeed.InventSiteId  = _priceChangeTracking.InventSiteId;
    priceDataFeed.UnitOfMeasure = _priceChangeTracking.UnitId;
    priceDataFeed.Quantity      = _priceChangeTracking.QuantityAmountFrom;
    priceDataFeed.StartDate     = _priceChangeTracking.FromDate;
    priceDataFeed.EndDate       = _priceChangeTracking.FromDate; //make EndDate same as StartDate
}

/// <summary>
/// Initilise values from the Original Price Change Tracking record
/// </summary>
public void initFromPriceChangeTracking()
{
    priceDataFeed.RefRecId      = priceChangeTrackingOrig.recId;
    priceDataFeed.RefTableId    = priceChangeTrackingOrig.tableId;
    priceDataFeed.ChangeType    = priceChangeTrackingOrig.ChangeType;
    priceDataFeed.DateOfChange  = priceChangeTrackingOrig.CreatedDateTime;
}

/// <summary>
/// get an inventory dimension id for
/// </summary>
/// <param name = "_inventSiteId">Site</param>
/// <returns>Inventory dimension id</returns>
public inventDimId getInventDimIdFromSite(InventSiteId _inventSiteId)
{   
    InventDim   inventDim;
    
    inventDim.clear();
    inventDim.InventSiteId = _inventSiteId;
    
    return InventDim::FindOrCreate(inventDim).inventDimId;
}

public InventSiteId getSiteFromInventDimId(InventDimId _inventDimId)
{
    return InventDim::find(_InventDimId).InventSiteId;
}

public UnitOfMeasureSymbol getUOMSymbolFromId(RefRecId _unitOfMeasure)
{
    return UnitOfMeasure::find(_unitOfMeasure).Symbol;
}

    /// <summary>
    /// Build a Query of Items
    /// </summary>
    /// <param name = "_pricingRuleCopy">Pricing Rule</param>
    /// <returns>Query</returns>
    public Query buildProductQueryBase(GUPPricingRuleCopy  _pricingRuleCopy)
    {
        Query                   productPreviewQuery;

        if(_pricingRuleCopy.PriceAttributeGroupName != '')
        {
            //build item list
            productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(_pricingRuleCopy).build();
        }

        return productPreviewQuery;
    }

    /// <summary>
    /// Build a Query of Customers
    /// </summary>
    /// <param name = "_pricingRuleCopyCustHeader">Pricing Rule</param>
    /// <returns>Query</returns>
    public Query buildCustQueryBase(GUPPricingRuleCopy  _pricingRuleCopyCustHeader)
    {
        Query                   custPreviewQuery;

        if (_pricingRuleCopyCustHeader.PriceAttributeGroupName != '')
        {
            //build customer list
            custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(_pricingRuleCopyCustHeader).build();
        }
        
        return custPreviewQuery;
    }

    /// <summary>
    /// Build a Set of Items
    /// </summary>
    /// <param name = "_productPreviewQuery">Item query</param>
    /// <param name = "_pricingRuleCopy">Pricing rule</param>
    /// <returns>Set of Items</returns>
    public Set buildItemValues(Query _productPreviewQuery, GUPPricingRuleCopy  _pricingRuleCopy)
    {
        Query               productPreviewQuery = _productPreviewQuery;
        QueryRun            productPreviewQueryRun;

        InventTable         inventTable;
        Set                 inventItemSet;

        if(productPreviewQuery)
        {
            productPreviewQueryRun = new QueryRun(productPreviewQuery);
            inventItemSet = new Set(Types::String);

            while(productPreviewQueryRun.next())
            {
                inventTable = productPreviewQueryRun.get(tableNum(InventTable));

                if(!GUPPricingRuleExclusionCopy::metExist(inventTable.ItemID, _pricingRuleCopy.ruleId))
                {
                    inventItemSet.add(inventTable.ItemID);
                }
            }
        }

        return inventItemSet;
    }

    /// <summary>
    /// Build a Set of Customers
    /// </summary>
    /// <param name = "_custPreviewQuery">Customer query</param>
    /// <param name = "_pricingRuleCopyCustHeader">Pricing rule header</param>
    /// <returns>Set of Customers</returns>
    public Set buildCustValues(Query  _custPreviewQuery, GUPPricingRuleCopy  _pricingRuleCopyCustHeader)
    {
        Query               custPreviewQuery = _custPreviewQuery;
        QueryRun            custPreviewQueryRun;
        CustTable           custTable;
        Set                 custAccountSet;

        if(custPreviewQuery)
        {
            custPreviewQueryRun = new QueryRun(custPreviewQuery);

            custAccountSet = new Set(Types::String);

            while(custPreviewQueryRun.next())
            {
                custTable = custPreviewQueryRun.get(tableNum(CustTable));

                if(!GUPPricingRuleExclusionCopy::metExist(custTable.AccountNum, _pricingRuleCopyCustHeader.ruleId))
                {
                    custAccountSet.add(custTable.AccountNum);
                }
            }
        }

        return custAccountSet;
    }

    /// <summary>
    /// Build an Enhanced Query of Customers
    /// </summary>
    /// <param name = "_pricingRuleCopyCustHeader">Pricing Rule</param>
    /// <param name = "_inventSiteId">Inventory site</param>
    /// <param name = "_groupAll">Group All</param>
    /// <returns>Query</returns>
    public Query buildCustQuery(GUPPricingRuleCopy  _pricingRuleCopyCustHeader, InventSiteId _inventSiteId, GUPGroupAll _groupAll)
    {
        Query               custPreviewQuery;
        QueryBuildDataSource    qbds;
        QueryBuildRange         qbr;

        if(_pricingRuleCopyCustHeader.PriceAttributeGroupName != '')
        {
            //build customer list
            custPreviewQuery = this.buildCustQueryBase(_pricingRuleCopyCustHeader);
        }
        else if(_groupAll == GUPGroupAll::All)
        {
            //need new query to select customers based on the Invent site
            //If there is no site, then we select ALL customers
            custPreviewQuery = new Query(queryStr(METCustTableInventSite));
        }

        //Filter by Site
        if(custPreviewQuery && _inventSiteId)
        {
            qbds = custPreviewQuery.dataSourceTable(tableNum(CustTable));
            qbr = SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, InventSiteId));
            qbr.value(queryValue(_inventSiteId));
        }

        return custPreviewQuery;
    }

    /// <summary>
    /// Send message to the Notification Centre
    /// </summary>
    /// <param name = "_message">Message</param>
    public void sendMessage(str _message)
    {
        SystemNotificationDataContract notification = new SystemNotificationDataContract();
        notification.Users().value(1, curUserId());
        notification.Title(strFmt("@MET:ValidationTrackingId", priceChangeTrackingOrig.TrackingId));
        notification.RuleId("@MET:PriceChangeTrackingRule");
        notification.Message(_message);
        notification.Severity(SystemNotificationSeverity::Informational);
        notification.ExpirationDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));

        SystemNotificationsManager::AddSystemNotification(notification);
    }

    /// <summary>
    /// Get the Expired Date
    /// </summary>
    /// <param name = "_toDate">current expire Date</param>
    /// <returns>Updated Expired date</returns>
    public TransDate getExpireDate(TransDate   _toDate)
    {
        TransDate   expireDate;
        TransDate   dateMax = 31\12\2099;

        expireDate = _toDate ? _toDate + 1 : dateMax ;

        return expireDate;
    }

    /// <summary>
    /// Get the From Date
    /// </summary>
    /// <param name = "_fromDate">current From Date</param>
    /// <returns>Updated From date</returns>
    public FromDate getFromDate(FromDate _fromDate)
    {
        FromDate    fromDate;

        fromDate = _fromDate ? _fromDate : todayDate;
        
        return fromDate;
    }

    /// <summary>
    /// Get the Unit of Measure
    /// </summary>
    /// <param name = "_unitOfMeasure">Unit of Measure</param>
    /// <param name = "_itemId">Current Item</param>
    /// <returns>Unit of Measure</returns>
    public METUnitOfMeasure getUnitOfMeasure(METUnitOfMeasure _unitOfMeasure, ItemId _itemId)
    {
        METUnitOfMeasure unitOfMeasure = _unitOfMeasure;

        if(!unitOfMeasure)
        {
            unitOfMeasure = InventTableModule::find(_itemId, ModuleInventPurchSales::Sales).UnitId;
        }
        return unitOfMeasure;
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    /// <param name = "_inventSiteId">Invent site</param>
    /// <param name = "_unitOfMeasure">Unit of Measure</param>
    /// <param name = "_lineNumber">line number</param>
    public void processMulti(Set _custAccountSet, Set _inventItemSet, InventSiteId _inventSiteId, METUnitOfMeasure _unitOfMeasure, LineNumber _lineNumber)
    {
        METPriceChangeTracking priceChangeTrackingUpdate;
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;
        boolean             validityCheck;
        METUnitOfMeasure    unitOfMeasure;

        if(_custAccountSet && _inventItemSet)
        {
            custAccountEnumerator = _custAccountSet.getEnumerator();

            while(custAccountEnumerator.moveNext())
            {
                custAccount = custAccountEnumerator.current();

                inventItemEnumerator = _inventItemSet.getEnumerator();

                while(inventItemEnumerator.moveNext())
                {
                    validityCheck = true;
                    inventItem  = inventItemEnumerator.current();
                    unitOfMeasure = this.getUnitOfMeasure(_unitOfMeasure, inventItem);

                    //1. Is there an Entry in Price Feed previously for Item number, Customer, Site, Unit of measure, From date, From quantity
                    if(!METPriceDataFeed::existForCustItem(custAccount,
                                                            inventItem,
                                                            _inventSiteId,
                                                            unitOfMeasure,
                                                            priceChangeTrackingOrig.FromDate,
                                                            priceChangeTrackingOrig.QuantityAmountFrom))
                    {
                        //2.Execute the Item/Site validity check
                        validityCheck = this.ItemSiteValidation(inventItem, _inventSiteId);

                        //3. Execute the Customer/Item validity check
                        validityCheck = validityCheck && this.CustomerItemValidation(custAccount, inventItem);
                                            
                        if(validityCheck)
                        {
                            //update priceChangeTracking values for processing, but dont committ to DB
                            buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);
                        
                            priceChangeTrackingUpdate.PriceDiscAccountRelation = custAccount;
                            priceChangeTrackingUpdate.ItemId                  = inventItem;
                            priceChangeTrackingUpdate.InventSiteId            = _inventSiteId;
                            priceChangeTrackingUpdate.UnitId                  = unitOfMeasure;

                            this.createPriceDataFeedAll(priceChangeTrackingUpdate, _lineNumber);
                        
                        }
                    }
                }
            }
        }
    }

    /// <summary>
    /// Create a Price data feed records from Related components
    /// </summary>
    /// <param name = "_priceChangeTracking">Change Tracking record</param>
    /// <param name = "_pricingRuleHeader">Header price rule</param>
    /// <param name = "_linePricingRule">Line price rule</param>
    /// <param name = "_groupAll">Group All</param>
    /// <param name = "_startDate">Start date</param>
    public void createRelatedComponentsBase(METPriceChangeTracking  _priceChangeTracking,
                                            LineNumber              _lineNumberOrig,
                                            RefRecId                _pricingRuleHeader,
                                            RefRecId                _linePricingRule,
                                            GUPGroupAll             _groupAll,
                                            TransDate               _startDate,
                                            METCreationType         _creationType,
                                            METChangeCodeRelated    _changeCodeRelated,
                                            METChangeCodeLineNumRelated _changeCodeLineNumRelated)
    {
        METPriceChangeTracking      priceChangeTrackingUpdate;
        Query                       custPreviewQuery;
        Query                       productPreviewQuery;
        GUPPricingRuleCopy          pricingRuleCopyCustHeader, pricingRuleCopy;
        QueryBuildDataSource        qbds;
        QueryBuildRange             qbr;

        if(_pricingRuleHeader != pricingRuleHeaderPrevious)
        {
            pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(_pricingRuleHeader));
            custPreviewQuery = this.buildCustQuery(pricingRuleCopyCustHeader, _priceChangeTracking.InventSiteId, _groupAll);
            
            //filter by the Customer
            qbds = custPreviewQuery.dataSourceTable(tableNum(CustTable));
            
            if(qbds)
            {
                qbr = SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum));
                qbr.value(queryValue(_priceChangeTracking.PriceDiscAccountRelation));
            }

            custAccountRelatedSet = this.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
        }
            
        if(_LinePricingRule != LinePricingRulePrevious)
        {
            pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(_linePricingRule));
            productPreviewQuery = this.buildProductQueryBase(pricingRuleCopy);
            
            //filter by the Item
            qbds = productPreviewQuery.dataSourceTable(tableNum(InventTable));
            
            if(qbds)
            {
                qbr = SysQuery::findOrCreateRange(qbds, fieldNum(InventTable, ItemId));
                qbr.value(queryValue(_priceChangeTracking.ItemId));
            }

            inventItemRelatedSet = this.buildItemValues(productPreviewQuery, pricingRuleCopy);
        }
            
        if(inventItemRelatedSet &&  
            custAccountRelatedSet && 
            inventItemRelatedSet.in(_priceChangeTracking.ItemId) && 
            custAccountRelatedSet.in(_priceChangeTracking.PriceDiscAccountRelation))
        {
            if(!METPriceDataFeed::existForCustItem(_priceChangeTracking.PriceDiscAccountRelation,
                                                        _priceChangeTracking.ItemId,
                                                        _priceChangeTracking.InventSiteId,
                                                        _priceChangeTracking.UnitId,
                                                        _startDate,
                                                        _priceChangeTracking.QuantityAmountFrom))
            {
                buf2Buf(_priceChangeTracking, priceChangeTrackingUpdate);
                //update priceChangeTracking values for processing, but dont committ to DB
                priceChangeTrackingUpdate.FromDate = _startDate;
                this.createPriceDataFeed(_creationType, priceChangeTrackingUpdate, _lineNumberOrig, _changeCodeRelated, _changeCodeLineNumRelated);
            }
        }

        pricingRuleHeaderPrevious = _pricingRuleHeader;
        linePricingRulePrevious = _linePricingRule;
    }

    /// <summary>
    /// Create a Price data feed records from Related components
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    public void createRelatedPriceAdj(METPriceChangeTracking _priceChangeTracking, 
                                        LineNumber          _lineNumberOriginal, 
                                        container           _discountTypesCon,
                                        METCreationType     _creationType)
    {
        RetailPeriodicDiscount      retailPeriodicDiscount;
        RetailPeriodicDiscountLine  retailPeriodicDiscountLine;
        InventDim                   inventDim;
        RefRecId                    pricingRuleHeader, linePricingRule;
        TransDate                   startDate;

        while select OfferId, HeaderPricingRule, ValidFrom, HeaderPricingGroupCode
            from    retailPeriodicDiscount
            where   retailPeriodicDiscount.OfferId      != _priceChangeTracking.DiscountCode
            &&      retailPeriodicDiscount.ValidTo      > _priceChangeTracking.FromDate
            &&      retailPeriodicDiscount.PeriodicDiscountType in _discountTypesCon
            &&      retailPeriodicDiscount.Status       == RetailDisabledEnabled::Enabled
            &&      retailPeriodicDiscount.IsGUPDiscount == NoYes::Yes
        join LinePricingRule, LineNum
            from    retailPeriodicDiscountLine
            where   retailPeriodicDiscountLine.OfferId  == retailPeriodicDiscount.OfferId
        exists join InventDim
            where   InventDim.InventDimId               == retailPeriodicDiscountLine.InventDimId
            &&      InventDim.InventSiteId              == _priceChangeTracking.InventSiteId
        {
            pricingRuleHeader   = retailPeriodicDiscount.HeaderPricingRule;
            linePricingRule     = retailPeriodicDiscountLine.LinePricingRule;
            startDate           = this.getFromDate(retailPeriodicDiscount.ValidFrom);

            this.createRelatedComponentsBase(_priceChangeTracking, 
                                            _lineNumberOriginal,
                                            pricingRuleHeader, 
                                            linePricingRule, 
                                            retailPeriodicDiscount.HeaderPricingGroupCode, 
                                            startDate, 
                                            _creationType,
                                            retailPeriodicDiscount.OfferId,
                                            retailPeriodicDiscountLine.LineNum);
        }
    }

    /// <summary>
    /// Create a Price data feed records from Related components
    /// </summary>
    /// <param name = "_priceChangeTracking">Change Tracking record</param>
    public void createRelatedAutoCharge(METPriceChangeTracking _priceChangeTracking, LineNumber _lineNumberOrig)
    {
        MarkupAutoLine          markupAutoLine;
        MarkupAutoTable         markupAutoTable;
        RefRecId                pricingRuleHeader, linePricingRule;
        TransDate               startDate;
        QueryBuildDataSource    qbdsLine;
        
        Query   query = new Query(queryStr(METMarkupAutoLineHeader));

        QueryRun    qr;

        qbdsLine = query.dataSourceTable(tableNum(MarkupAutoLine));

        qbdsLine.rangeField(fieldNum(MarkupAutoLine, RecId)).value(SysQuery::valueNot(_priceChangeTracking.RefRecId));
        qbdsLine.rangeField(fieldNum(MarkupAutoLine, ToDate)).value(SysQueryRangeUtil::metGreaterThanDate(_priceChangeTracking.FromDate));
        qbdsLine.rangeField(fieldNum(MarkupAutoLine, InventSiteId)).value(queryValue(_priceChangeTracking.InventSiteId));

        if(_priceChangeTracking.ChargeCodeModuleCategory == HeadingLine::Line)
        {
            qbdsLine.rangeField(fieldNum(MarkupAutoLine, MarkupCategory)).value(queryValue(MarkupCategory::Percent));
            qbdsLine.rangeField(fieldNum(MarkupAutoLine, MarkupCategory)).value(queryValue(MarkupCategory::Pcs));
        }

        qr = new QueryRun(query);

        while(qr.next())
        {
            markupAutoLine = qr.get(tableNum(markupAutoLine));
            markupAutoTable = qr.get(tableNum(MarkupAutoTable));

            pricingRuleHeader       = markupAutoLine.pricingRuleHeader ? markupAutoLine.pricingRuleHeader : markupAutoTable.PricingRuleHeader;
            linePricingRule         = markupAutoLine.PricingRuleLine ? markupAutoLine.PricingRuleLine : markupAutoTable.PricingRuleLine;
            startDate               = this.getFromDate(markupAutoLine.FromDate);

            this.createRelatedComponentsBase(_priceChangeTracking,
                                            _lineNumberOrig,
                                            pricingRuleHeader,
                                            linePricingRule,
                                            markupAutoTable.PricingGroupCodeHeader,
                                            startDate,
                                            METCreationType::RelatedAutoCharge,
                                            markupAutoTable.description,
                                            markupAutoLine.LineNum);
        }
    }

/// <summary>
/// Create a Price data feed record
/// </summary>
/// <param name = "_priceChangeTracking">Price change tracking</param>
/// <param name = "_lineNumber">Line number</param>
public void createPriceDataFeedAll(METPriceChangeTracking _priceChangeTrackingUpdate, LineNumber _lineNumber)
{
    this.createPriceDataFeed(this.getOriginalCreationType(), _priceChangeTrackingUpdate, _lineNumber);
    this.createRelatedComponents(_priceChangeTrackingUpdate, _lineNumber);
}

    /// <summary>
    /// Create a Price data feed record
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    /// <param name = "_lineNumber">Line number</param>
    /// <param name = "_creationType">Creation type</param>
    public void createPriceDataFeed(METCreationType             _creationType,
                                    METPriceChangeTracking      _priceChangeTracking,
                                    LineNumber                  _changeCodeLineNum,
                                    METChangeCodeRelated        _changeCodeRelated = "",
                                    METChangeCodeLineNumRelated _changeCodeLineNumRelated = 0)
    {
        this.createPriceDataFeedBase(_priceChangeTracking);

        priceDataFeed.ChangeCode                = this.getChangeCode(_priceChangeTracking);
        priceDataFeed.ChangeCodeLineNum         = _changeCodeLineNum;
        priceDataFeed.CreationType              = _creationType;
        priceDataFeed.ChangeCodeRelated         = _changeCodeRelated;
        priceDataFeed.ChangeCodeLineNumRelated  = _changeCodeLineNumRelated;
        priceDataFeedList.add(priceDataFeed);
        priceDataFeedCount++;
    }

