{
}

abstract METChangeCode getChangeCode(METPriceChangeTracking _priceChangeTracking)
{
}

abstract METCreationType getRelatedCreationType()
{
}

abstract void createRelatedComponents(METPriceChangeTracking _priceChangeTracking, LineNumber _LineNumberOrig)
{
}
